insert into axes (key, road_fr, road_en, title_fr, title_en, pitch_fr, pitch_en, vehicle_hint_fr, vehicle_hint_en, accent, position) values
  ('tana', 'Ville & environs', 'City & surroundings', 'Antananarivo & environs', 'Antananarivo & surroundings', 'Avant de prendre la route, la capitale et ses environs offrent deja un concentre de culture malgache et de nature protegee, a moins d une heure du centre-ville.', 'Before hitting the road, the capital and its surroundings already pack in Malagasy culture and protected nature, all within an hour of downtown.', 'Berline ou SUV', 'Sedan or SUV', 'clay', 0),
  ('rn2', 'RN2 - vers l Est', 'RN2 - towards the East', 'RN2 : forets orientales et ocean', 'RN2: eastern rainforest and ocean', 'De Tana a Toamasina, la RN2 traverse les hautes terres puis plonge dans la foret humide de l Est, jusqu aux plages et au canal des Pangalanes.', 'From Tana to Toamasina, the RN2 crosses the highlands then dives into the eastern rainforest, all the way to the beaches and the Pangalanes canal.', 'SUV conseille', 'SUV recommended', 'canopy', 1),
  ('rn7', 'RN7 - vers le Sud', 'RN7 - towards the South', 'RN7 : la grande traversee du Sud', 'RN7: the great southern crossing', 'La route la plus mythique de Madagascar : artisanat des hautes terres, forets tropicales, canyons de gres et immensites du Sud jusqu a Toliara.', 'Madagascar most legendary road: highland craftsmanship, tropical rainforest, sandstone canyons and the vast southern landscapes down to Toliara.', 'SUV ou van', 'SUV or van', 'ember', 2),
  ('rn34', 'RN34 - vers Morondava', 'RN34 - towards Morondava', 'RN34 : baobabs et tsingy de l Ouest', 'RN34: baobabs and western tsingy', 'Route mythique vers Morondava, la foret seche, l allee des baobabs et les tsingy de Bemaraha, en 4x4 pour la partie non revetue.', 'The legendary road to Morondava, dry forest, the Avenue of the Baobabs and the Bemaraha tsingy, by 4x4 on the unpaved stretch.', '4x4 obligatoire', '4x4 required', 'clay', 3),
  ('rn4', 'RN4 - vers le Nord-Ouest', 'RN4 - towards the North-West', 'RN4 : vers Mahajanga', 'RN4: towards Mahajanga', 'De Tana a Mahajanga, la RN4 traverse une foret seche protegee puis rejoint la cote au climat chaud et aux falaises de laterite rouge.', 'From Tana to Mahajanga, the RN4 crosses a protected dry forest before reaching a warm coast lined with red laterite cliffs.', 'Berline ou SUV', 'Sedan or SUV', 'canopy', 4),
  ('rn6', 'RN6 - Grand Nord', 'RN6 - Far North', 'RN6 : Diego Suarez et Nosy Be', 'RN6: Diego Suarez and Nosy Be', 'L extreme Nord malgache : baies decoupees, montagnes couvertes de foret, formations de laterite et les plages tropicales de Nosy Be.', 'The far north of Madagascar: jagged bays, forested mountains, red laterite formations and the tropical beaches of Nosy Be.', 'SUV ou 4x4', 'SUV or 4x4', 'lagoon', 5);
insert into sites (axis_key, name, badge_fr, badge_en, description_fr, description_en, tags, image_url, lat, lng, position) values
  ('tana', 'Palais de la Reine (Rova)', 'Patrimoine royal', 'Royal heritage', 'Ancienne residence fortifiee des souverains merina, perchee sur la colline d Analamanga avec une vue panoramique sur toute la capitale.', 'Former fortified residence of the Merina sovereigns, perched on Analamanga hill with a panoramic view over the whole capital.', ARRAY['culture', 'panorama']::text[], 'https://commons.wikimedia.org/wiki/Special:Redirect/file/Manjakamiadana%20-%20Rova%20of%20Antananarivo%20-%20Queen''s%20Palace.jpg?width=1200', -18.92365, 47.53202, 0),
  ('tana', 'Village d art malgache d Ambohitrimanjaka', 'Artisanat', 'Craft village', 'Village lacustre entoure de rizieres, reconnu pour ses ateliers de peinture et d artisanat malgache traditionnel.', 'A village surrounded by rice paddies, known for its Malagasy painting and traditional craft workshops.', ARRAY['artisanat', 'culture']::text[], null, -18.8675, 47.4538, 1),
  ('tana', 'Lemurs Park', 'Lemuriens', 'Lemurs', 'Parc botanique prive le long de la riviere Katsaoka, ou plusieurs especes de lemuriens evoluent en semi-liberte au milieu d une foret replantee.', 'Private botanical park along the Katsaoka river, where several lemur species roam semi-free in a replanted forest.', ARRAY['lemuriens', 'famille']::text[], 'https://commons.wikimedia.org/wiki/Special:Redirect/file/Ring%20Tailed%20Lemur%20in%20Lemur''s%20Park.jpg?width=1200', -18.9524028, 47.3575361, 2),
  ('tana', 'Katsaoka & Imeritsiatosika', 'Hautes terres', 'Highlands', 'Commune des hautes terres traversee par la riviere Katsaoka, entre rizieres en terrasses et collines cultivees : une pause nature facile depuis Tana.', 'A highland town crossed by the Katsaoka river, between terraced rice paddies and farmed hills — an easy nature break from Tana.', ARRAY['nature', 'rizieres']::text[], null, -18.983, 47.317, 3),
  ('rn2', 'Lac Mantasoa', 'Lac & foret', 'Lake & forest', 'Vaste lac artificiel entoure de pins et d eucalyptus, prise pour la voile, la peche et les balades en foret a 1h30 de Tana.', 'A large artificial lake surrounded by pine and eucalyptus forest, popular for sailing, fishing and forest walks 1.5h from Tana.', ARRAY['lac', 'detente']::text[], 'https://commons.wikimedia.org/wiki/Special:Redirect/file/Mantasoa%20lakeside.jpg?width=1200', -19.0208, 47.8599, 0),
  ('rn2', 'Nosy Soa Park', 'Reserve privee', 'Private reserve', 'Petite reserve privee sur l axe de Moramanga, dediee a la decouverte de la faune et de la flore locales dans un cadre preserve.', 'A small private reserve on the Moramanga road, dedicated to discovering local wildlife and flora in a protected setting.', ARRAY['nature', 'faune']::text[], 'https://commons.wikimedia.org/wiki/Special:Redirect/file/Maki%20catta%20en%20qu%C3%AAte%20de%20la%20prochaine%20banane-Nosy%20Soa%20Park%20Mantasoa-Mars%202024.jpg?width=1200', -18.9913, 47.8855, 1),
  ('rn2', 'Reserve Peyrieras Exotic Park (Mandraka)', 'Reptiles & insectes', 'Reptiles & insects', 'Parc prive de Mandraka specialise dans les cameleons, geckos, grenouilles et insectes de Madagascar, tres photogenique et pedagogique.', 'Private park in Mandraka specialised in Madagascar chameleons, geckos, frogs and insects — highly photogenic and educational.', ARRAY['reptiles', 'photo']::text[], 'https://commons.wikimedia.org/wiki/Special:Redirect/file/Common%20Tenrec%201.JPG?width=1200', -18.931306, 47.949972, 2),
  ('rn2', 'Parc National Andasibe-Mantadia', 'Indri indri', 'Indri lemur', 'Le chant du lemurien indri indri resonne dans cette foret primaire, l un des sites les plus visites de Madagascar, a 3-4h de Tana.', 'The call of the indri lemur echoes through this primary forest, one of Madagascar most visited sites, 3-4h from Tana.', ARRAY['foret', 'lemuriens']::text[], 'https://commons.wikimedia.org/wiki/Special:Redirect/file/Indri%20Andasibe.JPG?width=1200', -18.93611, 48.42833, 3),
  ('rn2', 'Palmarium (Manambato)', 'Reserve privee', 'Private reserve', 'Reserve privee au bord du lac Ampitabe, sur le canal des Pangalanes, accessible en pirogue depuis Manambato, connue pour ses lemuriens tres proches et son jardin botanique.', 'Private reserve on Lake Ampitabe, on the Pangalanes canal, reached by canoe from Manambato, known for very close lemur encounters and its botanical garden.', ARRAY['lemuriens', 'lac']::text[], 'https://commons.wikimedia.org/wiki/Special:Redirect/file/Plage%20de%20sable%20blanc%20de%20Palmarium%20Reserve%2C%20Manambato%2C%20Atsinanana%20region%2C%20Madagascar.jpg?width=1200', -18.6060183, 49.2106766, 4),
  ('rn2', 'Toamasina (Tamatave)', 'Port & Pangalanes', 'Port & Pangalanes', 'Premier port de Madagascar, porte d entree du canal des Pangalanes, avec ses avenues bordees de flamboyants et ses marches animes.', 'Madagascar largest port, gateway to the Pangalanes canal, with avenues lined with flame trees and lively markets.', ARRAY['ville', 'cote']::text[], 'https://commons.wikimedia.org/wiki/Special:Redirect/file/Port%20Toamasina%20Madagascar.jpg?width=1200', -18.155, 49.41, 5),
  ('rn2', 'Ile Sainte Marie', 'Ile & baleines', 'Island & whales', 'Ile paradisiaque au large de Toamasina, celebre pour ses plages, ses fonds coralliens et l observation des baleines a bosse entre juillet et septembre.', 'A paradise island off Toamasina, famous for its beaches, coral reefs and humpback whale watching between July and September.', ARRAY['ile', 'plage', 'baleines']::text[], 'https://commons.wikimedia.org/wiki/Special:Redirect/file/Beache%20of%20La%20Crique%20Sainte%20Marie.jpg?width=1200', -16.96667, 49.86667, 6),
  ('rn7', 'Forgerons d Ambatolampy', 'Artisanat', 'Craft', 'Ville reputee pour ses fonderies artisanales d aluminium recycle, ou marmites et objets sont coules a la main devant les visiteurs.', 'A town known for its artisanal recycled-aluminium foundries, where pots and tools are hand-cast in front of visitors.', ARRAY['artisanat', 'culture']::text[], 'https://commons.wikimedia.org/wiki/Special:Redirect/file/Artisans%20(%20cuill%C3%A8res%20en%20aluminium%20).jpg?width=1200', -19.38611, 47.42917, 0),
  ('rn7', 'Fabrication de miniatures a Antsirabe', 'Artisanat', 'Craft', 'Capitale thermale des hautes terres, celebre pour ses pousse-pousse decores et ses ateliers de voitures miniatures en boites de conserve recyclees.', 'The highlands thermal capital, famous for its decorated rickshaws and workshops making miniature cars from recycled tin cans.', ARRAY['artisanat', 'ville']::text[], 'https://commons.wikimedia.org/wiki/Special:Redirect/file/Antsirabe%20miniature%20bicycle%20maker.jpg?width=1200', -19.86611, 47.03306, 1),
  ('rn7', 'Sculpture d Ambositra et village des Zafimaniry', 'Patrimoine UNESCO', 'UNESCO heritage', 'Capitale malgache du bois sculpte, porte d entree vers les villages Zafimaniry dont le savoir-faire de marqueterie est classe par l UNESCO.', 'Madagascar wood-carving capital, gateway to the Zafimaniry villages whose marquetry craftsmanship is UNESCO-listed.', ARRAY['artisanat', 'unesco']::text[], 'https://commons.wikimedia.org/wiki/Special:Redirect/file/Zafimaniry%20house.JPG?width=1200', -20.51667, 47.25, 2),
  ('rn7', 'Parc National de Ranomafana', 'Foret tropicale', 'Rainforest', 'Foret tropicale humide abritant le lemurien aux bambous dore, des sources thermales et un reseau de sentiers entre cascades et riviere.', 'Humid rainforest home to the golden bamboo lemur, hot springs and a trail network winding past waterfalls and the river.', ARRAY['foret', 'lemuriens', 'sources chaudes']::text[], 'https://commons.wikimedia.org/wiki/Special:Redirect/file/Namorona%20River%20in%20Ranomafana%20National%20Park%202013%201.jpg?width=1200', -21.21667, 47.41667, 3),
  ('rn7', 'Sahambavy', 'Plantation de the', 'Tea plantation', 'Seule plantation de the de Madagascar, nichee dans des collines verdoyantes pres de Fianarantsoa, avec visite des jardins et de l usine.', 'Madagascar only tea plantation, set in green hills near Fianarantsoa, with tours of the gardens and the factory.', ARRAY['agriculture', 'panorama']::text[], 'https://commons.wikimedia.org/wiki/Special:Redirect/file/Plantation%20de%20th%C3%A9%20%C3%A0%20Sahambavy.JPG?width=1200', -21.43333, 47.28333, 4),
  ('rn7', 'Parc National Andringitra (Fianarantsoa)', 'Montagnes', 'Mountains', 'Massif granitique abritant le Pic Boby, deuxieme sommet de Madagascar, avec des paysages de haute montagne et une biodiversite exceptionnelle.', 'A granite massif home to Pic Boby, Madagascar second-highest peak, with high-mountain scenery and exceptional biodiversity.', ARRAY['randonnee', 'montagne']::text[], 'https://commons.wikimedia.org/wiki/Special:Redirect/file/Andringitra%2C%20Madagascar%20by%20Effervescing%20Elephant-01.jpg?width=1200', -22.11278, 46.92306, 5),
  ('rn7', 'Reserve communautaire Anja (Ambalavao)', 'Makis catta', 'Ring-tailed lemurs', 'Reserve geree par la communaute locale, connue pour ses colonies de makis catta evoluant librement au milieu des blocs de granite.', 'A community-managed reserve famous for its ring-tailed lemur colonies roaming freely among granite boulders.', ARRAY['lemuriens', 'communautaire']::text[], 'https://commons.wikimedia.org/wiki/Special:Redirect/file/Ring-Tailed%20Lemur%20Calling%2C%20Anja%20Reserve%20(3953855032).jpg?width=1200', -21.85203, 46.84278, 6),
  ('rn7', 'Parc National de l Isalo', 'Canyons de gres', 'Sandstone canyons', 'Massif de gres sculpte par l erosion : piscines naturelles, canyon des Singes, canyon des Rats et couchers de soleil sur la Fenetre de l Isalo.', 'A sandstone massif carved by erosion: natural pools, Monkey Canyon, Rat Canyon and sunsets at the Isalo Window rock formation.', ARRAY['canyons', 'randonnee', 'iconique']::text[], 'https://commons.wikimedia.org/wiki/Special:Redirect/file/Isalo%20-%20Namaza%20-%20piscine%20naturelle.jpg?width=1200', -22.43333, 45.35, 7),
  ('rn7', 'Toliara (Tulear) et ses sites', 'Sud & lagon', 'South & lagoon', 'Ville du bout de la RN7, tremplin vers Ifaty, les recifs coralliens, les baobabs du Sud et l arboretum d Antsokay.', 'The town at the end of the RN7, springboard to Ifaty, coral reefs, southern baobabs and the Antsokay arboretum.', ARRAY['plage', 'baobabs', 'lagon']::text[], 'https://commons.wikimedia.org/wiki/Special:Redirect/file/City%20Centre%20Toliara%202007.jpg?width=1200', -23.35, 43.66667, 8),
  ('rn34', 'Allee des Baobabs (Morondava)', 'Site iconique', 'Iconic site', 'Alignement spectaculaire de baobabs geants vieux de 800 ans, incontournable au coucher du soleil, a 20 minutes de Morondava.', 'A spectacular row of 800-year-old giant baobabs, unmissable at sunset, 20 minutes from Morondava.', ARRAY['baobabs', 'photo', 'iconique']::text[], 'https://commons.wikimedia.org/wiki/Special:Redirect/file/All%C3%A9e%20des%20Baobabs%20near%20Morondava%2C%20Madagascar.jpg?width=1200', -20.2503, 44.4193, 0),
  ('rn34', 'Tsingy de Bemaraha (Grand et Petit Tsingy)', 'UNESCO', 'UNESCO', 'Labyrinthe de pinacles calcaires classe au patrimoine mondial, explore via des parcours cables suspendus entre les aiguilles de pierre.', 'A labyrinth of limestone pinnacles listed as a World Heritage site, explored via via-ferrata style routes among the stone spires.', ARRAY['4x4', 'unesco', 'aventure']::text[], 'https://commons.wikimedia.org/wiki/Special:Redirect/file/Grand%20Tsingy%2001.JPG?width=1200', -18.9135, 44.7944, 1),
  ('rn34', 'Grotte et gorges de la Manambolo', 'Grotte & riviere', 'Cave & river', 'Descente en pirogue des gorges de la Manambolo, ponctuee par la visite d une grotte sacree et de falaises calcaires abruptes.', 'A canoe trip through the Manambolo gorges, punctuated by a visit to a sacred cave and steep limestone cliffs.', ARRAY['riviere', 'grotte']::text[], 'https://commons.wikimedia.org/wiki/Special:Redirect/file/Gorges%20du%20Manambolo%2C%20Morondava%2C%20Madagascar.jpg?width=1200', -19.1353, 44.8463, 2),
  ('rn34', 'Foret de Kirindy', 'Foret seche', 'Dry forest', 'Foret seche protegee abritant le fossa, plus grand predateur de Madagascar, et plusieurs especes de lemuriens nocturnes.', 'A protected dry forest home to the fossa, Madagascar largest predator, and several nocturnal lemur species.', ARRAY['foret', 'faune nocturne']::text[], 'https://commons.wikimedia.org/wiki/Special:Redirect/file/Baobab%20Kirindy%20Forest%20Madagascar%20-%20panoramio.jpg?width=1200', -20.0675, 44.5957, 3),
  ('rn34', 'Akiba Lodge', 'Etape nature', 'Nature stopover', 'Etape lodge au calme entre foret et rizieres sur la route de Bekopaka, ideale pour couper la longue piste vers les tsingy.', 'A quiet lodge stopover between forest and rice paddies on the road to Bekopaka, ideal for breaking up the long track to the tsingy.', ARRAY['hebergement', 'detente']::text[], null, -20.1334, 44.5483, 4),
  ('rn34', 'Village des pecheurs de Betania', 'Vie locale', 'Local life', 'Village de pecheurs traditionnels aux portes de Morondava, pirogues a balancier et scenes de vie cotiere authentiques.', 'A traditional fishing village on the edge of Morondava, outrigger canoes and authentic coastal life.', ARRAY['culture', 'cote']::text[], 'https://commons.wikimedia.org/wiki/Special:Redirect/file/Fisherman''s%20Village%20in%20Morondava%2C%20Madagascar%20-%20panoramio.jpg?width=1200', -20.30874, 44.26488, 5),
  ('rn34', 'Parc Zazamalala', 'Reserve privee', 'Private reserve', 'Reserve privee de foret seche pres de Belo-sur-Tsiribihina, dediee a la conservation de la faune locale et a l ecotourisme.', 'A private dry-forest reserve near Belo-sur-Tsiribihina, dedicated to conserving local wildlife and ecotourism.', ARRAY['nature', 'conservation']::text[], null, -20.3391, 44.5736, 6),
  ('rn34', 'Descente de la Tsiribihina', 'Aventure fluviale', 'River adventure', 'Descente en pirogue ou en bateau du fleuve Tsiribihina sur plusieurs jours, entre villages riverains, bivouacs sur plage et faune sauvage.', 'A multi-day canoe or boat descent of the Tsiribihina river, between riverside villages, beach camps and wildlife.', ARRAY['riviere', 'aventure']::text[], 'https://commons.wikimedia.org/wiki/Special:Redirect/file/Pirogue%20Madagascar.jpg?width=1200', -19.5556, 45.4508, 7),
  ('rn4', 'Parc National Ankarafantsika', 'Foret seche', 'Dry forest', 'Grande foret seche traversee directement par la RN4, refuge de baobabs, de sifakas et d une riche avifaune autour du lac Ravelobe.', 'A large dry forest crossed directly by the RN4, home to baobabs, sifaka lemurs and rich birdlife around Lake Ravelobe.', ARRAY['foret seche', 'oiseaux']::text[], 'https://commons.wikimedia.org/wiki/Special:Redirect/file/Western%20Dry%20Deciduous%20Forest%2C%20Ankarafantsika%20National%20Park%2C%20Madagascar%20(4026813379).jpg?width=1200', -16.3157, 46.8066, 0),
  ('rn4', 'Circuit Rouge (Mahajanga)', 'Falaises de laterite', 'Laterite cliffs', 'Falaises et canyons de laterite rouge aux formes sculptees par l erosion, aux portes de Mahajanga, spectaculaires au coucher du soleil.', 'Red laterite cliffs and canyons carved by erosion at the edge of Mahajanga, spectacular at sunset.', ARRAY['laterite', 'photo']::text[], 'https://commons.wikimedia.org/wiki/Special:Redirect/file/Le%20Cirque%20Rouge%20de%20Mahajanga.jpg?width=1200', -15.6346426, 46.3530648, 1),
  ('rn4', 'Grotte de Belobaka', 'Grotte sacree', 'Sacred cave', 'Reseau de grottes calcaires sacrees pres de Mahajanga, avec stalactites, chauve-souris et un lieu de culte traditionnel toujours actif.', 'A sacred limestone cave network near Mahajanga, with stalactites, bats and a still-active traditional place of worship.', ARRAY['grotte', 'culture']::text[], 'https://commons.wikimedia.org/wiki/Special:Redirect/file/La%20Grotte%20Belobaka.jpg?width=1200', -15.6986249, 46.4038925, 2),
  ('rn6', 'Tsingy Rouge', 'Formation unique', 'Unique formation', 'Pinacles de laterite rouge et blanche sculptes par l erosion, un decor lunaire spectaculaire a moins d une heure de Diego Suarez.', 'Red and white laterite pinnacles carved by erosion, a spectacular moon-like landscape under an hour from Diego Suarez.', ARRAY['laterite', 'photo']::text[], 'https://commons.wikimedia.org/wiki/Special:Redirect/file/Tsingy%20rouge%20de%20Diego%2001.jpg?width=1200', -12.63889, 49.49722, 0),
  ('rn6', 'Baie de Sakalava', 'Kitesurf', 'Kitesurfing', 'Grande baie ventee prisee des amateurs de kitesurf, avec eaux turquoise et dunes de sable a proximite de Diego Suarez.', 'A large windy bay popular with kitesurfers, with turquoise waters and sand dunes near Diego Suarez.', ARRAY['plage', 'sport']::text[], 'https://commons.wikimedia.org/wiki/Special:Redirect/file/Baie%20de%20Sakalava%2001.jpg?width=1200', -12.26667, 49.4, 1),
  ('rn6', 'Lac sacre Antanavo (Anivorano)', 'Lac aux crocodiles', 'Crocodile lake', 'Lac sacre pres d Anivorano-Nord, reconnu pour ses crocodiles consideres comme sacres par les communautes locales.', 'A sacred lake near Anivorano-Nord, known for crocodiles regarded as sacred by local communities.', ARRAY['lac', 'culture']::text[], 'https://commons.wikimedia.org/wiki/Special:Redirect/file/Lieu%20de%20culte%20au%20lac%20sacr%C3%A9%20Antagnavo.jpg?width=1200', -12.75, 49.25, 2),
  ('rn6', 'Plage de Ramena', 'Plage', 'Beach', 'Village de pecheurs et plage de sable blanc pres de Diego Suarez, point de depart des excursions vers les trois baies et Nosy Lonjo.', 'A fishing village and white sand beach near Diego Suarez, starting point for trips to the three bays and Nosy Lonjo.', ARRAY['plage', 'famille']::text[], 'https://commons.wikimedia.org/wiki/Special:Redirect/file/La%20plage%20Ramena%20Antsiranana%20Madagascar.jpg?width=1200', -12.2333, 49.35, 3),
  ('rn6', 'Cap d Ambre', 'Extreme Nord', 'Northern tip', 'Point le plus septentrional de Madagascar, phare isole battu par les vents entre ocean Indien et canal du Mozambique.', 'Madagascar northernmost point, an isolated wind-swept lighthouse between the Indian Ocean and the Mozambique Channel.', ARRAY['aventure', 'panorama']::text[], null, -11.95639, 49.2725, 4),
  ('rn6', 'Montagne des Francais', 'Randonnee', 'Hiking', 'Massif rocheux surplombant la baie de Diego Suarez, entre foret seche, grottes et vestiges militaires, avec vue panoramique.', 'A rocky massif overlooking Diego Suarez bay, mixing dry forest, caves and military ruins, with panoramic views.', ARRAY['randonnee', 'panorama']::text[], 'https://commons.wikimedia.org/wiki/Special:Redirect/file/Montagne%20des%20Francais%20Antsiranana%20Madagascar%20-%20panoramio.jpg?width=1200', -12.34111, 49.34528, 5),
  ('rn6', 'Parc National Montagne d Ambre', 'Foret d altitude', 'Montane forest', 'Foret humide d altitude aux cascades et lacs de cratere, refuge de plusieurs especes de cameleons et de lemuriens endemiques.', 'A humid montane forest with waterfalls and crater lakes, home to several endemic chameleon and lemur species.', ARRAY['foret', 'cascades']::text[], 'https://commons.wikimedia.org/wiki/Special:Redirect/file/Cascade%20sacr%C3%A9%20de%20la%20montagne%20d''ambre.jpg?width=1200', -12.595, 49.155, 6),
  ('rn6', 'Nosy Be, Hell-Ville et ses sites', 'Ile aux parfums', 'Perfume island', 'Ile principale de l archipel, entre marche animes de Hell-Ville, plantations d ylang-ylang, Mont Passot et plages d Andilana ou Nosy Komba.', 'The main island of the archipelago, from the lively markets of Hell-Ville to ylang-ylang plantations, Mont Passot and the beaches of Andilana or Nosy Komba.', ARRAY['ile', 'plage', 'nature']::text[], 'https://commons.wikimedia.org/wiki/Special:Redirect/file/Mont%20Passot.jpg?width=1200', -13.4, 48.26667, 7);
insert into vehicles (name, type_fr, type_en, seats, bags, terrain_fr, terrain_en, fuel_fr, fuel_en, rate, available, image_url, position) values
  ('Kia Pride', 'Citadine', 'City car', 4, 2, 'Ville et route bitumee', 'City and paved road', 'Essence', 'Petrol', 120000, 3, 'https://commons.wikimedia.org/wiki/Special:Redirect/file/1993%20Kia%20Pride%20LX%20(14594988361).jpg?width=1200', 0),
  ('Hyundai Starex 4x4', 'Van 4x4', '4x4 Van', 7, 5, 'Route et piste legere', 'Road and light track', 'Diesel', 'Diesel', 320000, 3, 'https://commons.wikimedia.org/wiki/Special:Redirect/file/Hyundai%20H1%20HSV%202.4%204x4%202001%20(15604806109).jpg?width=1200', 1),
  ('Hyundai Grand Starex', 'Van premium', 'Premium van', 8, 6, 'Route confort, longues distances', 'Comfort road, long distances', 'Diesel', 'Diesel', 355000, 2, 'https://commons.wikimedia.org/wiki/Special:Redirect/file/Hyundai%20Grand%20Starex%20VIP%20rear.jpg?width=1200', 2),
